// Generated by build.py from the actual distribution, including art and fonts.
const CACHE = "warzone-__BUILD_HASH__";
const FILES = __PRECACHE_FILES__;
const READY = "./offline-ready";
async function broadcast(data) {
  for (const client of await self.clients.matchAll({ includeUncontrolled: true }))
    client.postMessage(data);
}
self.addEventListener("install", (event) =>
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      let done = 0;
      try {
        // Sequential puts avoid downloading several large packages simultaneously.
        for (const path of FILES) {
          const response = await fetch(new Request(path, { cache: "reload" }));
          if (!response.ok) throw Error(`Could not cache ${path}`);
          await cache.put(path, response);
          await broadcast({ type: "offline-progress", done: ++done, total: FILES.length });
        }
        await cache.put(READY, new Response("ready"));
        await broadcast({ type: "offline-ready" });
        // The old worker continues serving its live game until its tabs close.
      } catch (error) {
        await caches.delete(CACHE);
        await broadcast({ type: "offline-error" });
        throw error;
      }
    })(),
  ),
);
self.addEventListener("activate", (event) =>
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys())
        if (name.startsWith("warzone-") && name !== CACHE) await caches.delete(name);
      await self.clients.claim();
    })(),
  ),
);
self.addEventListener("message", (event) => {
  if (event.data?.type === "offline-status")
    event.waitUntil(
      (async () => {
        const cache = await caches.open(CACHE);
        // Older installations have no sentinel; the active worker is upgraded
        // only after all files of this build have been installed successfully.
        if (await cache.match(READY)) event.source?.postMessage({ type: "offline-ready" });
      })(),
    );
});
self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET" || new URL(event.request.url).origin !== location.origin)
    return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      if (event.request.mode === "navigate") {
        const url = new URL(event.request.url);
        const root = new URL("./", self.location.href).pathname;
        if (url.pathname === root || url.pathname === `${root}index.html`) {
          // Fresh HTML selects a coherent versioned bundle online. Offline, use
          // the last completely installed document and its matching resources.
          try {
            return await fetch(event.request);
          } catch {
            return cache.match("./");
          }
        }
      }
      const cached = await cache.match(event.request);
      if (cached) return cached;
      return fetch(event.request);
    })(),
  );
});
